-- FULL INSTALLATION of the Ether Mines database. FILE GENERATED by tools/installation.mjs: do not edit by hand.
-- Contains: 001_schema.sql, 002_security.sql, 003_moderation.sql, 004_chests.sql, 005_usernames.sql, 006_public_zones.sql, 007_network.sql, 008_trades.sql, 009_onchain_wallet.sql, 010_bed.sql, 011_toggle_public.sql, 012_relight_column.sql, 013_mob_loot.sql, 014_relight_capstone.sql, 015_boss_loot.sql, 016_tower_boss_loot.sql, then rules.sql.
-- Run all at once in Supabase (SQL Editor). Safe to re-run. To start from scratch: reset.sql first.

-- ════════════════ 001_schema.sql ════════════════
-- 001: Ether Mines full schema.
-- The server is authoritative: players cannot write directly to the world or to their inventory.
-- Every action (mine, place, craft...) goes through an act_* function that checks the rules then applies them.
-- Prerequisite: Authentication → Sign In / Providers → "Allow anonymous sign-ins" enabled.
-- Then: run supabase/rules.sql (game rules generated from the code) and deploy the "freeze" function.
-- Later migrations: additive only.

create extension if not exists pgcrypto with schema extensions;

-- =========================================================================================
-- 1. The world
-- =========================================================================================

-- Frozen original terrain, per 16x16-column chunk. Written only by the "freeze" function,
-- which generates it server-side with the same generator as the game: a player can't invent terrain.
create table if not exists public.chunks (
  world      text        not null,
  cx         integer     not null,
  cz         integer     not null,
  gen        integer     not null,   -- generator version
  sy         integer     not null,   -- world height (64)
  data       text        not null,   -- blocks encoded as runs (length, block) then base64
  created_at timestamptz not null default now(),
  primary key (world, cx, cz)
);
alter table public.chunks enable row level security;
drop policy if exists "read chunks" on public.chunks;
create policy "read chunks" on public.chunks for select using (true);

-- Modified blocks. Written only by the act_* functions.
create table if not exists public.blocks (
  world        text        not null,
  x            integer     not null,
  y            integer     not null,
  z            integer     not null,
  id           smallint    not null,
  placed_by    text,       -- author's account, null for a mined block
  placed_name  text,
  serial       integer,
  updated_at   timestamptz not null default now(),
  primary key (world, x, y, z)
);
create index if not exists blocks_zone on public.blocks (world, x, z);
create index if not exists blocks_author on public.blocks (world, placed_by) where placed_by is not null;
alter table public.blocks enable row level security;
drop policy if exists "read blocks" on public.blocks;
create policy "read blocks" on public.blocks for select using (true);

-- Claims: a claimed chunk can only be modified by its owner and their guests.
create table if not exists public.claims (
  world       text        not null,
  cx          integer     not null,
  cz          integer     not null,
  owner       uuid        not null references auth.users (id) on delete cascade,
  owner_name  text,
  members     uuid[]      not null default '{}',
  created_at  timestamptz not null default now(),
  primary key (world, cx, cz)
);
create index if not exists claims_owner on public.claims (world, owner);
alter table public.claims enable row level security;
drop policy if exists "read claims" on public.claims;
create policy "read claims" on public.claims for select using (true);

-- =========================================================================================
-- 2. Players
-- =========================================================================================

-- Each player's game, per world. The client can only write its own preferences (state: hotbar, position,
-- seen quests, log); arbitration counters are server-only.
create table if not exists public.players (
  user_id    uuid        not null references auth.users (id) on delete cascade,
  world      text        not null,
  name       text,
  color      text,
  state      jsonb       not null default '{}'::jsonb,
  serial     integer     not null default 0,      -- number of the last block placed
  mine_at    timestamptz,                         -- last block mined (mining speed)
  rewards_at timestamptz,                         -- last validator reward
  gifts      jsonb       not null default '{}'::jsonb, -- today's animal gifts
  muted_until timestamptz,
  mutes      integer     not null default 0,
  pos_x      real,
  pos_y      real,
  pos_z      real,
  pos_at     timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, world)
);
alter table public.players enable row level security;
drop policy if exists "read own game" on public.players;
create policy "read own game" on public.players for select to authenticated using (auth.uid() = user_id);
drop policy if exists "create own game" on public.players;
create policy "create own game" on public.players for insert to authenticated
  with check (auth.uid() = user_id and char_length(world) between 1 and 32 and pg_column_size(state) < 300000);
drop policy if exists "save own game" on public.players;
create policy "save own game" on public.players for update to authenticated
  using (auth.uid() = user_id) with check (auth.uid() = user_id and pg_column_size(state) < 300000);
revoke insert, update, delete on public.players from anon, authenticated;
grant insert (user_id, world, name, color, state, updated_at) on public.players to authenticated;
grant update (user_id, world, name, color, state, updated_at) on public.players to authenticated; -- user_id and world: needed for upsert, bounded by the "save own game" rule

-- Inventory: quantities per item. Read-only for the player.
create table if not exists public.inventory (
  user_id  uuid     not null references auth.users (id) on delete cascade,
  world    text     not null,
  item     smallint not null,
  n        integer  not null check (n >= 0),
  primary key (user_id, world, item)
);
alter table public.inventory enable row level security;
drop policy if exists "read own inventory" on public.inventory;
create policy "read own inventory" on public.inventory for select to authenticated using (auth.uid() = user_id);

-- Unique items (future NFTs): numbered per player, with their history.
create table if not exists public.uniques (
  user_id    uuid        not null references auth.users (id) on delete cascade,
  world      text        not null,
  serial     integer     not null,
  item       smallint    not null,
  place      text,
  mined      integer     not null default 0,
  vx         integer,
  vy         integer,
  vz         integer,
  chain_tx   text,       -- mint tx hash, filled in by the operator
  token_id   text,       -- on-chain token id once minted (kept as text to avoid JS precision loss)
  created_at timestamptz not null default now(),
  primary key (user_id, world, serial)
);
alter table public.uniques enable row level security;
drop policy if exists "read own uniques" on public.uniques;
create policy "read own uniques" on public.uniques for select to authenticated using (auth.uid() = user_id);

-- Recovery codes (only the hash is kept).
create table if not exists public.recovery (
  user_id    uuid        primary key references auth.users (id) on delete cascade,
  code_hash  text        not null unique,
  created_at timestamptz not null default now()
);
alter table public.recovery enable row level security;

-- =========================================================================================
-- 3. Rules (filled in by supabase/rules.sql, generated from the game code)
-- =========================================================================================
create table if not exists public.rule_blocks (
  id        smallint primary key,
  name      text,
  hard      real,       -- seconds by hand; null = unbreakable
  tier      smallint not null default 0,  -- required tool tier
  drop_item smallint,   -- what it drops (null = nothing)
  kind      text not null,               -- cube, cross, water, slab, stairs, door, lever, plate, cable
  solid     boolean not null,
  top       boolean not null default false
);
create table if not exists public.rule_place (item smallint not null, block smallint not null, primary key (item, block));
create table if not exists public.rule_items (id smallint primary key, name text, tool real not null default 1, tier smallint not null default 0, uniq boolean not null default false);
create table if not exists public.rule_recipes (out_item smallint primary key, n integer not null, need jsonb not null, uniq boolean not null default false);
alter table public.rule_blocks enable row level security;
alter table public.rule_place enable row level security;
alter table public.rule_items enable row level security;
alter table public.rule_recipes enable row level security;

-- =========================================================================================
-- 4. Internal tools (not callable by players)
-- =========================================================================================

-- Current block at (x, y, z): known edit if any, otherwise frozen terrain. Chunk not frozen yet: "freeze" error.
create or replace function public._cell(w text, px int, py int, pz int) returns smallint
language plpgsql stable security definer set search_path = public as $$
declare v smallint; c record; b bytea; idx int; acc int := 0; i int := 0; r int; n int;
begin
  if py < 0 or py >= 64 then return 0; end if;
  select id into v from blocks where world = w and x = px and y = py and z = pz;
  if found then return v; end if;
  select sy, data into c from chunks where world = w and cx = px >> 4 and cz = pz >> 4;
  if not found then raise exception 'freeze:%,%', px >> 4, pz >> 4; end if;
  if py >= c.sy then return 0; end if;
  b := decode(c.data, 'base64'); idx := (px & 15) + (pz & 15) * 16 + py * 256; n := length(b);
  while i + 1 < n loop
    r := get_byte(b, i);
    if idx < acc + r then return get_byte(b, i + 1); end if;
    acc := acc + r; i := i + 2;
  end loop;
  return 0;
end $$;

create or replace function public._set(w text, px int, py int, pz int, bid int, who uuid, who_name text, ser int) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  insert into blocks (world, x, y, z, id, placed_by, placed_name, serial, updated_at)
    values (w, px, py, pz, bid, who::text, who_name, ser, now())
    on conflict (world, x, y, z) do update set id = excluded.id, placed_by = excluded.placed_by,
      placed_name = excluded.placed_name, serial = excluded.serial, updated_at = now();
  return jsonb_build_object('x', px, 'y', py, 'z', pz, 'id', bid, 'by', who, 'name', who_name, 'serial', ser);
end $$;

-- Change the block without touching its signature (doors, levers).
create or replace function public._flip(w text, px int, py int, pz int, bid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare r blocks;
begin
  insert into blocks (world, x, y, z, id) values (w, px, py, pz, bid)
    on conflict (world, x, y, z) do update set id = excluded.id, updated_at = now() returning * into r;
  return jsonb_build_object('x', px, 'y', py, 'z', pz, 'id', bid, 'by', r.placed_by, 'name', r.placed_name, 'serial', r.serial);
end $$;

create or replace function public._player(me uuid, w text) returns public.players
language plpgsql security definer set search_path = public as $$
declare p players;
begin
  if me is null then raise exception 'not signed in'; end if;
  if char_length(w) not between 1 and 32 then raise exception 'invalid world'; end if;
  insert into players (user_id, world) values (me, w) on conflict do nothing;
  select * into p from players where user_id = me and world = w for update;
  return p;
end $$;

create or replace function public._count(me uuid, w text, it int) returns int
language sql stable security definer set search_path = public as $$
  select coalesce((select n from inventory where user_id = me and world = w and item = it), 0)
$$;

-- Adds (or removes, if d < 0) items from the inventory; returns the changed inventory slice in inv.
create or replace function public._give(me uuid, w text, it int, d int, inv jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v int;
begin
  if d < 0 then
    update inventory set n = n + d where user_id = me and world = w and item = it returning n into v;
    if v is null or v < 0 then raise exception 'not enough in inventory'; end if;
  else
    insert into inventory (user_id, world, item, n) values (me, w, it, d)
      on conflict (user_id, world, item) do update set n = inventory.n + d returning n into v;
  end if;
  return inv || jsonb_build_object(it::text, v);
end $$;

create or replace function public._mint(me uuid, w text, it int, where_ text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare s int;
begin
  select coalesce(max(serial), 0) + 1 into s from uniques where user_id = me and world = w;
  insert into uniques (user_id, world, serial, item, place) values (me, w, s, it, where_);
  return jsonb_build_object('serial', s, 'id', it, 'place', where_, 'date', to_char(now(), 'DD/MM/YYYY'), 'mined', 0);
end $$;

-- The sanctuary is untouchable; a claim can only be modified by its owner and their guests.
create or replace function public._can_build(me uuid, w text, px int, pz int) returns boolean
language sql stable security definer set search_path = public as $$
  select not (px between 4 and 12 and pz between 4 and 12)
     and not exists (select 1 from claims c where c.world = w and c.cx = px >> 4 and c.cz = pz >> 4
                     and c.owner <> me and not (me = any (c.members)))
$$;

create or replace function public._no(msg text, extra jsonb default '{}'::jsonb) returns jsonb
language sql immutable as $$ select jsonb_build_object('ok', false, 'err', msg) || extra $$;

-- =========================================================================================
-- 5. Player actions (business logic — wrapped by rate/position checks in 002_security.sql)
-- =========================================================================================

-- Mine: tool strong enough, plausible pace, loot picked by the server.
create or replace function public._core_mine(w text, px int, py int, pz int, held text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; id0 int; rb rule_blocks; t_tier int := 0; t_mult real := 1; useri int;
  need real; ch jsonb := '[]'; inv jsonb := '{}'; oy int; other int; above int; ab rule_blocks; n int;
begin
  pl := _player(me, w);
  id0 := _cell(w, px, py, pz);
  select * into rb from rule_blocks where id = id0;
  if id0 = 0 or rb.id is null or rb.hard is null then return _no('nothing to mine', jsonb_build_object('cell', id0)); end if;
  if not _can_build(me, w, px, pz) then return _no('protected', jsonb_build_object('cell', id0)); end if;
  if held = '102' and _count(me, w, 102) > 0 then
    select tier, rule_items.tool into t_tier, t_mult from rule_items where id = 102;
  elsif held like 'nft%' then
    select u.serial, i.tier, i.tool into useri, t_tier, t_mult from uniques u join rule_items i on i.id = u.item
      where u.user_id = me and u.world = w and u.serial = nullif(substr(held, 4), '')::int;
    t_tier := coalesce(t_tier, 0); t_mult := coalesce(t_mult, 1);
  end if;
  if t_tier < rb.tier then return _no('tool too weak', jsonb_build_object('cell', id0)); end if;
  need := rb.hard / t_mult;
  if pl.mine_at is not null and extract(epoch from clock_timestamp() - pl.mine_at) < need * 0.5 - 0.1 then
    return _no('too fast', jsonb_build_object('cell', id0));
  end if;
  update players set mine_at = clock_timestamp() where user_id = me and world = w;
  ch := ch || _set(w, px, py, pz, 0, null, null, null);
  if rb.kind = 'door' then
    oy := case when rb.top then py - 1 else py + 1 end; other := _cell(w, px, oy, pz);
    if (select kind from rule_blocks where id = other) = 'door' then ch := ch || _set(w, px, oy, pz, 0, null, null, null); end if;
  end if;
  above := _cell(w, px, py + 1, pz); select * into ab from rule_blocks where id = above;
  if ab.kind = 'cross' then ch := ch || _set(w, px, py + 1, pz, 0, null, null, null);
  elsif ab.kind in ('plate', 'cable', 'lever') then
    ch := ch || _set(w, px, py + 1, pz, 0, null, null, null);
    if ab.drop_item is not null then inv := _give(me, w, ab.drop_item, 1, inv); end if;
  end if;
  n := case rb.drop_item when 101 then 1 + (random() < 0.4)::int when 104 then (random() < 0.4)::int else 1 end;
  if rb.drop_item is not null and n > 0 then inv := _give(me, w, rb.drop_item, n, inv); end if;
  if useri is not null then update uniques set mined = mined + 1 where user_id = me and world = w and serial = useri; end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'got', jsonb_build_object('item', rb.drop_item, 'n', n));
end $$;

-- Place: the item is in the inventory, the cell is free, the support is right.
create or replace function public._core_place(w text, px int, py int, pz int, it int, bid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; cur int; cr rule_blocks; rb rule_blocks; below int; up int; ch jsonb := '[]'; inv jsonb := '{}'; s int;
begin
  pl := _player(me, w);
  if py < 1 or py >= 64 or abs(px) >= 100000 or abs(pz) >= 100000 then return _no('out of the world'); end if;
  if not exists (select 1 from rule_place where item = it and block = bid) then return _no('item not placeable'); end if;
  if _count(me, w, it) < 1 then return _no('empty inventory', jsonb_build_object('inv', jsonb_build_object(it::text, 0))); end if;
  if not _can_build(me, w, px, pz) then return _no('protected'); end if;
  cur := _cell(w, px, py, pz); select * into cr from rule_blocks where id = cur;
  if cur <> 0 and cr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', cur)); end if;
  select * into rb from rule_blocks where id = bid;
  below := _cell(w, px, py - 1, pz);
  if rb.kind = 'cross' and below not in (1, 2) then return _no('needs support'); end if;
  if rb.kind in ('plate', 'cable', 'lever') and not coalesce((select solid from rule_blocks where id = below), false) then return _no('needs support'); end if;
  if rb.kind = 'door' then
    if py + 1 >= 64 then return _no('out of the world'); end if;
    up := _cell(w, px, py + 1, pz);
    if up <> 0 and (select kind from rule_blocks where id = up) not in ('water', 'cross') then return _no('space occupied'); end if;
  end if;
  inv := _give(me, w, it, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, bid, me, pl.name, s);
  if rb.kind = 'door' then ch := ch || _set(w, px, py + 1, pz, bid + 1, me, pl.name, s); end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'serial', s);
end $$;

-- Open a door, flip a lever.
create or replace function public._core_toggle(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); cur int; rb rule_blocks; ch jsonb := '[]'; oy int; other int;
begin
  perform _player(me, w);
  cur := _cell(w, px, py, pz); select * into rb from rule_blocks where id = cur;
  if rb.kind not in ('door', 'lever') then return _no('nothing to toggle', jsonb_build_object('cell', cur)); end if;
  if not _can_build(me, w, px, pz) then return _no('protected'); end if;
  if rb.kind = 'lever' then return jsonb_build_object('ok', true, 'changes', ch || _flip(w, px, py, pz, case cur when 64 then 65 else 64 end)); end if;
  ch := ch || _flip(w, px, py, pz, cur # 2);
  oy := case when rb.top then py - 1 else py + 1 end; other := _cell(w, px, oy, pz);
  if (select kind from rule_blocks where id = other) = 'door' then ch := ch || _flip(w, px, oy, pz, other # 2); end if;
  return jsonb_build_object('ok', true, 'changes', ch);
end $$;

-- Craft according to a recipe known to the server.
create or replace function public._core_craft(w text, out_id int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); r rule_recipes; k text; v jsonb; inv jsonb := '{}'; u jsonb;
begin
  perform _player(me, w);
  select * into r from rule_recipes where out_item = out_id;
  if not found then return _no('unknown recipe'); end if;
  for k, v in select * from jsonb_each(r.need) loop
    if _count(me, w, k::int) < v::int then return _no('missing ingredients', jsonb_build_object('item', k::int)); end if;
  end loop;
  for k, v in select * from jsonb_each(r.need) loop inv := _give(me, w, k::int, -(v::int), inv); end loop;
  if r.uniq then u := _mint(me, w, out_id, null); return jsonb_build_object('ok', true, 'inv', inv, 'unique', u); end if;
  inv := _give(me, w, out_id, r.n, inv);
  return jsonb_build_object('ok', true, 'inv', inv);
end $$;

-- Relight a dark validator with a validator heart (allowed even inside a claim).
create or replace function public._core_relight(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}'; s int; ch jsonb := '[]'; u jsonb;
begin
  pl := _player(me, w);
  if _cell(w, px, py, pz) <> 73 then return _no('not a dark validator', jsonb_build_object('cell', _cell(w, px, py, pz))); end if;
  if _count(me, w, 105) < 1 then return _no('needs a validator heart'); end if;
  inv := _give(me, w, 105, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, 74, me, pl.name, s);
  u := _mint(me, w, 203, px || ', ' || py || ', ' || pz);
  update uniques set vx = px, vy = py, vz = pz where user_id = me and world = w and serial = (u ->> 'serial')::int;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'unique', u, 'serial', s);
end $$;

-- Gift from a petted animal: once a day per animal, fifteen a day at most.
create or replace function public._core_gift(w text, animal text, kind text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; today text := to_char(now(), 'YYYY-MM-DD'); g jsonb; it int; inv jsonb := '{}';
begin
  pl := _player(me, w);
  if animal is null or char_length(animal) > 40 then return _no('unknown animal'); end if;
  if pl.created_at > now() - interval '30 minutes' then return _no('the animals do not know you yet'); end if;
  g := coalesce((select jsonb_object_agg(k, v) from jsonb_each(pl.gifts) e(k, v) where v #>> '{}' = today), '{}');
  if g ? animal then return _no('already gifted today'); end if;
  if (select count(*) from jsonb_object_keys(g)) >= 15 then return _no('enough gifts for today'); end if;
  it := case kind when 'sheep' then 71 when 'fox' then 17 + floor(random() * 3)::int when 'jellyfish' then 101 else null end;
  if it is null then return _no('this animal has no gift'); end if;
  update players set gifts = g || jsonb_build_object(animal, today) where user_id = me and world = w;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

-- Validator rewards for blocks the player has signed: in "shares" per 12s slot, 25 shares = 1 crystal.
--   placed validator: 1 share (1 crystal every 5 minutes), at most 5 placed validators count;
--   relit dark validator: 5 shares (1 crystal per minute).
-- Only validators already placed at the start of the paid period count. Unconverted shares aren't lost
-- (remaining time carries over). At most 30 minutes caught up at once.
create or replace function public._core_rewards(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; placed int; relit int; shares int; slots int; gain int; used int;
        start_at timestamptz; inv jsonb := '{}';
begin
  pl := _player(me, w);
  if pl.rewards_at is null then
    update players set rewards_at = now() where user_id = me and world = w;
    return jsonb_build_object('ok', true, 'inv', inv, 'slots', 0, 'weight', 0, 'n', 0);
  end if;
  start_at := greatest(pl.rewards_at, now() - interval '30 minutes');      -- limited catch-up
  select count(*) filter (where id = 13), count(*) filter (where id = 74) into placed, relit
    from blocks where world = w and placed_by = me::text and id in (13, 74) and updated_at <= start_at;
  shares := least(placed, 5) + 5 * relit;
  if shares = 0 then
    update players set rewards_at = now() where user_id = me and world = w;
    return jsonb_build_object('ok', true, 'inv', inv, 'slots', 0, 'weight', 0, 'n', 0);
  end if;
  slots := floor(extract(epoch from now() - start_at) / 12)::int;
  gain := floor(slots * shares / 25.0)::int;
  if gain < 1 then
    if start_at <> pl.rewards_at then update players set rewards_at = start_at where user_id = me and world = w; end if;
    return jsonb_build_object('ok', true, 'inv', inv, 'slots', 0, 'weight', shares, 'n', 0);
  end if;
  used := ceil(gain * 25.0 / shares)::int;                                -- slots consumed; the rest waits
  update players set rewards_at = start_at + make_interval(secs => used * 12) where user_id = me and world = w;
  inv := _give(me, w, 101, gain, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'slots', used, 'weight', shares, 'n', gain);
end $$;

-- Claims: 2 crystals per chunk, 16 at most per player, never the sanctuary chunk.
create or replace function public._core_claim(w text, qx int, qz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}';
begin
  pl := _player(me, w);
  if qx = 0 and qz = 0 then return _no('the sanctuary belongs to everyone'); end if;
  if abs(qx) > 6250 or abs(qz) > 6250 then return _no('out of the world'); end if;
  if exists (select 1 from claims where world = w and cx = qx and cz = qz) then return _no('already claimed'); end if;
  if (select count(*) from claims where world = w and owner = me) >= 16 then return _no('16 claims at most'); end if;
  if _count(me, w, 101) < 2 then return _no('needs 2 ether crystals'); end if;
  inv := _give(me, w, 101, -2, inv);
  insert into claims (world, cx, cz, owner, owner_name, members)
    select w, qx, qz, me, pl.name, coalesce((select members from claims where world = w and owner = me limit 1), '{}');
  return jsonb_build_object('ok', true, 'inv', inv);
end $$;

create or replace function public._core_unclaim(w text, qx int, qz int) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  delete from claims where world = w and cx = qx and cz = qz and owner = auth.uid();
  if not found then return _no('not your claim'); end if;
  return jsonb_build_object('ok', true);
end $$;

-- Invite (or kick) a player, by their username, on all of their claims in the world.
create or replace function public._core_member(w text, username text, invite boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); who uuid; wname text;
begin
  select user_id, name into who, wname from players where world = w and lower(name) = lower(trim(username)) and user_id <> me
    order by updated_at desc limit 1;
  if who is null then return _no('unknown player in this world'); end if;
  if invite then update claims set members = array_append(array_remove(members, who), who) where world = w and owner = me;
  else update claims set members = array_remove(members, who) where world = w and owner = me; end if;
  return jsonb_build_object('ok', true, 'name', wname);
end $$;

-- =========================================================================================
-- 6. Recovery codes
-- =========================================================================================
create or replace function public.set_recovery_code() returns text
language plpgsql security definer set search_path = public, extensions as $$
declare raw text; code text;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  raw := upper(encode(extensions.gen_random_bytes(8), 'hex'));
  code := substr(raw, 1, 4) || '-' || substr(raw, 5, 4) || '-' || substr(raw, 9, 4) || '-' || substr(raw, 13, 4);
  insert into public.recovery (user_id, code_hash) values (auth.uid(), encode(extensions.digest(code, 'sha256'), 'hex'))
    on conflict (user_id) do update set code_hash = excluded.code_hash, created_at = now();
  return code;
end $$;

-- Reattaches to the connected player everything owned by that code's account: games, inventories,
-- unique items, blocks, claims.
create or replace function public._core_claim_recovery(code text) returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare old uuid; me uuid := auth.uid(); n integer;
begin
  if me is null then raise exception 'not signed in'; end if;
  select user_id into old from public.recovery where code_hash = encode(extensions.digest(upper(trim(code)), 'sha256'), 'hex');
  if old is null then raise exception 'unknown code'; end if;
  if old = me then return 0; end if;
  -- this device's account steps aside for the code's account, world by world
  delete from public.inventory i where i.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = i.world);
  delete from public.uniques u where u.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = u.world);
  delete from public.players p where p.user_id = me and exists (select 1 from public.players o where o.user_id = old and o.world = p.world);
  update public.players set user_id = me where user_id = old;
  get diagnostics n = row_count;
  update public.inventory set user_id = me where user_id = old;
  update public.uniques set user_id = me where user_id = old;
  update public.blocks set placed_by = me::text where placed_by = old::text;
  update public.claims set owner = me where owner = old;
  update public.claims set members = array_replace(members, old, me) where old = any (members);
  delete from public.recovery where user_id = me;
  update public.recovery set user_id = me where user_id = old;
  return n;
end $$;

-- =========================================================================================
-- 7. Rights and live broadcast
-- =========================================================================================
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_' or p.proname in ('set_recovery_code', 'claim_recovery')) loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

do $$ begin
  begin alter publication supabase_realtime add table public.blocks; exception when duplicate_object then null; end;
  begin alter publication supabase_realtime add table public.claims; exception when duplicate_object then null; end;
end $$;

-- ════════════════ 002_security.sql ════════════════
-- 002: action security.
--   1. Rate limits: a player can't call faster than a human could.
--   2. Reach and movement: every action on a block sends the player's position; the block must be in
--      reach, and the position must be reachable from the previous one.
-- Requires 001_schema.sql (_core_* functions, _no, _can_build...). Replayable without error.

-- ---------- 1. rate limits (token bucket per player and action kind) ----------
create table if not exists public.rate_limits (
  user_id uuid        not null references auth.users (id) on delete cascade,
  kind    text        not null,
  tokens  real        not null,
  at      timestamptz not null default now(),
  primary key (user_id, kind)
);
alter table public.rate_limits enable row level security; -- no policy: functions only

-- Consumes a token if possible. per_s: tokens regained per second; burst: maximum reserve.
create or replace function public._rate(me uuid, kind_ text, per_s real, burst real) returns boolean
language plpgsql security definer set search_path = public as $$
declare r rate_limits; t real;
begin
  select * into r from rate_limits where user_id = me and kind = kind_ for update;
  if not found then
    insert into rate_limits (user_id, kind, tokens, at) values (me, kind_, burst - 1, clock_timestamp()) on conflict do nothing;
    return true;
  end if;
  t := least(burst, r.tokens + per_s * extract(epoch from clock_timestamp() - r.at));
  if t < 1 then
    update rate_limits set tokens = t, at = clock_timestamp() where user_id = me and kind = kind_;
    return false;
  end if;
  update rate_limits set tokens = t - 1, at = clock_timestamp() where user_id = me and kind = kind_;
  return true;
end $$;
grant execute on function public._rate(uuid, text, real, real) to service_role; -- called directly by the "freeze" Edge Function

-- ---------- 2. player position ----------
alter table public.players add column if not exists pos_x real;
alter table public.players add column if not exists pos_y real;
alter table public.players add column if not exists pos_z real;
alter table public.players add column if not exists pos_at timestamptz;

-- Checks that a reported position is plausible (reachable from the last known one, or a permitted
-- teleport) and, if a target is given, that it's within reach. Stores the position if all is well.
-- Returns null if ok, otherwise the refusal reason.
create or replace function public._check_pos(me uuid, w text, ex real, ey real, ez real, tx int default null, ty int default null, tz int default null)
returns text language plpgsql security definer set search_path = public as $$
declare p players; dt real; horiz real; up real; ok boolean := false;
begin
  if ex is null or ey is null or ez is null then return 'missing position'; end if;
  if abs(ex) > 100000 or abs(ez) > 100000 or ey < -20 or ey > 80 then return 'position out of the world'; end if;
  select * into p from players where user_id = me and world = w;
  if p.pos_at is null then ok := true;                                   -- first known position
  else
    dt := greatest(extract(epoch from clock_timestamp() - p.pos_at), 0);
    horiz := sqrt((ex - p.pos_x) ^ 2 + (ez - p.pos_z) ^ 2);
    up := ey - p.pos_y;                                                  -- falls aren't limited
    ok := horiz <= 9 * dt + 8 and up <= 9 * dt + 6;                       -- 6.6 blocks/s running pace, with slack for network lag
    if not ok then ok := sqrt((ex - 8.5) ^ 2 + (ez - 10.5) ^ 2) <= 8; end if; -- return to the sanctuary (/sanctuary, falling into the void)
    if not ok then                                                        -- /join: next to a recently-active player
      ok := exists (select 1 from players o where o.world = w and o.user_id <> me and o.pos_at > clock_timestamp() - interval '2 minutes'
                    and sqrt((ex - o.pos_x) ^ 2 + (ez - o.pos_z) ^ 2) <= 6);
    end if;
  end if;
  if not ok then return 'impossible move'; end if;
  if tx is not null and sqrt((tx + 0.5 - ex) ^ 2 + (ty + 0.5 - (ey + 1.6)) ^ 2 + (tz + 0.5 - ez) ^ 2) > 6.5 then
    return 'too far';
  end if;
  update players set pos_x = ex, pos_y = ey, pos_z = ez, pos_at = clock_timestamp() where user_id = me and world = w;
  return null;
end $$;

-- Cell content, used to fix up the client's display after a refusal; null if the chunk isn't frozen yet.
create or replace function public._cell_soft(w text, x int, y int, z int) returns int
language plpgsql security definer set search_path = public as $$
begin
  return _cell(w, x, y, z);
exception when others then
  return null;
end $$;

create or replace function public._me_or_fail(w text) returns uuid
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform _player(auth.uid(), w);
  return auth.uid();
end $$;

-- ---------- rate + position + reach, then the game rule ----------
create or replace function public.act_mine(w text, px int, py int, pz int, held text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'mine', 8, 16) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez, px, py, pz);
  if e is not null then return _no(e, jsonb_build_object('cell', _cell_soft(w, px, py, pz))); end if;
  return _core_mine(w, px, py, pz, held);
end $$;

create or replace function public.act_place(w text, px int, py int, pz int, it int, bid int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'place', 8, 16) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez, px, py, pz);
  if e is not null then return _no(e, jsonb_build_object('cell', _cell_soft(w, px, py, pz))); end if;
  -- don't place a solid block inside your own body
  if (select solid from rule_blocks where id = bid) and (select kind from rule_blocks where id = bid) not in ('door')
     and px + 1 > ex - 0.3 and px < ex + 0.3 and pz + 1 > ez - 0.3 and pz < ez + 0.3 and py + 1 > ey and py < ey + 1.75 then
    return _no('space occupied');
  end if;
  return _core_place(w, px, py, pz, it, bid);
end $$;

create or replace function public.act_toggle(w text, px int, py int, pz int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'toggle', 4, 8) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez, px, py, pz);
  if e is not null then return _no(e); end if;
  return _core_toggle(w, px, py, pz);
end $$;

create or replace function public.act_relight(w text, px int, py int, pz int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'relight', 1, 3) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez, px, py, pz);
  if e is not null then return _no(e); end if;
  return _core_relight(w, px, py, pz);
end $$;

-- Simple position ping (every ~15s while moving): used by /join and keeps the server-side position fresh.
create or replace function public.act_pos(w text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'pos', 0.5, 3) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.act_craft(w text, out_id int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'craft', 4, 12) then return _no('too many actions'); end if;
  return _core_craft(w, out_id);
end $$;

create or replace function public.act_gift(w text, animal text, kind text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'gift', 0.5, 3) then return _no('too many actions'); end if;
  return _core_gift(w, animal, kind);
end $$;

create or replace function public.act_rewards(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'rewards', 0.1, 2) then return jsonb_build_object('ok', true, 'inv', '{}'::jsonb, 'slots', 0); end if;
  return _core_rewards(w);
end $$;

-- Claim: must be standing inside the claimed chunk.
create or replace function public.act_claim(w text, qx int, qz int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'claim', 0.5, 3) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  if floor(ex)::int >> 4 <> qx or floor(ez)::int >> 4 <> qz then return _no('must be inside the claim'); end if;
  return _core_claim(w, qx, qz);
end $$;

create or replace function public.act_unclaim(w text, qx int, qz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'claim', 0.5, 3) then return _no('too many actions'); end if;
  return _core_unclaim(w, qx, qz);
end $$;

create or replace function public.act_member(w text, username text, invite boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'member', 0.5, 4) then return _no('too many actions'); end if;
  return _core_member(w, username, invite);
end $$;

-- Recovery codes: at most one attempt every few seconds (against mass guessing).
-- An unknown code returns -1 instead of an error: an error would also roll back the consumed token.
create or replace function public.claim_recovery(code text) returns integer
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not _rate(auth.uid(), 'recovery', 0.2, 3) then raise exception 'too many attempts, wait a moment'; end if;
  begin
    return _core_claim_recovery(code);
  exception when raise_exception then
    if sqlerrm = 'unknown code' then return -1; end if;
    raise;
  end;
end $$;

-- ---------- rights: only act_* and the recovery functions are callable by players ----------
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_' or p.proname in ('set_recovery_code', 'claim_recovery')) loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 003_moderation.sql ════════════════
-- 003: server-arbitrated chat, reports, and client error logging.
--   1. Chat goes through act_chat: username and color taken from the player's own game record (no
--      speaking as someone else), rate limited, length capped, banned words masked, muted players refused.
--   2. /report: three different players (who have already played) within 24h mute a player (1h, doubling
--      on each repeat offense).
--   3. log_error: players' JavaScript errors land in the client_errors table (kept 14 days).
-- Requires 002_security.sql (_rate, _me_or_fail). Replayable without error.

-- ---------- 1. chat ----------
create table if not exists public.chat (
  id      bigint generated always as identity primary key,
  world   text        not null,
  user_id uuid        not null references auth.users (id) on delete cascade,
  name    text        not null,
  color   text        not null,
  text    text        not null,
  at      timestamptz not null default now()
);
create index if not exists chat_world_at on public.chat (world, at);
alter table public.chat enable row level security;
drop policy if exists "read chat" on public.chat;
create policy "read chat" on public.chat for select using (true);
revoke insert, update, delete on public.chat from anon, authenticated;

-- Masked words in chat (compared without accents or case, whole word). Extendable by hand:
--   insert into chat_banned_words values ('word') on conflict do nothing;
create table if not exists public.chat_banned_words (word text primary key);
alter table public.chat_banned_words enable row level security; -- no policy: functions only
insert into public.chat_banned_words values
  ('fuck'), ('fucking'), ('shit'), ('bitch'), ('cunt'), ('asshole'), ('bastard'), ('slut'), ('whore'),
  ('dick'), ('pussy'), ('nigger'), ('nigga'), ('faggot'), ('retard')
on conflict do nothing;

create or replace function public._strip_accents(t text) returns text language sql immutable as $$
  select translate(lower(t), 'àâäáãåçéèêëíìîïñóòôöõúùûüýÿœæ', 'aaaaaaceeeeiiiinooooouuuuyyoa') $$;

-- Replaces each banned word with stars, leaving the rest of the message as is.
create or replace function public._mask(t text) returns text
language plpgsql stable security definer set search_path = public as $$
declare m record; base text := _strip_accents(t); out_ text := t; pos int; l int;
begin
  for m in select word from chat_banned_words loop
    l := char_length(m.word);
    loop
      -- first occurrence of the whole word (no letter or digit around it)
      select min(s.i) into pos from generate_series(1, char_length(base) - l + 1) s(i)
       where substr(base, s.i, l) = m.word
         and (s.i = 1 or substr(base, s.i - 1, 1) !~ '[a-z0-9]')
         and (s.i + l > char_length(base) or substr(base, s.i + l, 1) !~ '[a-z0-9]');
      exit when pos is null;
      out_ := overlay(out_ placing repeat('*', l) from pos for l);
      base := overlay(base placing repeat('*', l) from pos for l);
    end loop;
  end loop;
  return out_;
end $$;

create or replace function public.act_chat(w text, msg text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); p players; t text; c text;
begin
  if octet_length(coalesce(msg, '')) > 1000 then return _no('message too long'); end if;
  select * into p from players where user_id = me and world = w;
  if p.muted_until > now() then
    return _no('muted', jsonb_build_object('minutes', ceil(extract(epoch from p.muted_until - now()) / 60)));
  end if;
  if not _rate(me, 'chat', 1, 4) then return _no('too many actions'); end if;
  -- control characters stripped, whitespace collapsed, 140 characters at most
  t := left(btrim(regexp_replace(regexp_replace(coalesce(msg, ''), '[[:cntrl:]]', ' ', 'g'), '\s+', ' ', 'g')), 140);
  if t = '' then return _no('empty message'); end if;
  t := _mask(t);
  c := case when p.color ~ '^#[0-9a-fA-F]{6}$' then p.color else '#cccccc' end;
  insert into chat (world, user_id, name, color, text) values (w, me, left(coalesce(nullif(btrim(p.name), ''), 'anonymous'), 20), c, t);
  if random() < 0.02 then delete from chat where at < now() - interval '2 days'; end if;
  return jsonb_build_object('ok', true, 'text', t);
end $$;

-- ---------- 2. reports ----------
create table if not exists public.reports (
  world    text        not null,
  reporter uuid        not null references auth.users (id) on delete cascade,
  target   uuid        not null references auth.users (id) on delete cascade,
  at       timestamptz not null default now(),
  primary key (world, reporter, target)
);
alter table public.reports enable row level security; -- no policy: functions only

create or replace function public.act_report(w text, username text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); tgt players; n int; d interval;
begin
  if not _rate(me, 'report', 0.1, 5) then return _no('too many actions'); end if;
  -- against throwaway accounts made to silence someone: must have genuinely played in this world
  if not exists (select 1 from players where user_id = me and world = w and serial >= 20
                 and created_at < now() - interval '2 hours') then
    return _no('must have played a little');
  end if;
  select * into tgt from players where world = w and lower(name) = lower(btrim(left(username, 40))) and user_id <> me limit 1;
  if tgt.user_id is null then return _no('unknown player'); end if;
  insert into reports (world, reporter, target) values (w, me, tgt.user_id)
    on conflict (world, reporter, target) do update set at = now();
  select count(*) into n from reports where world = w and target = tgt.user_id and at > now() - interval '24 hours';
  if n >= 3 and coalesce(tgt.muted_until, '-infinity') < now() then
    d := interval '1 hour' * power(2, least(tgt.mutes, 4));   -- at most 16 hours
    update players set muted_until = now() + d, mutes = mutes + 1 where user_id = tgt.user_id and world = w;
    delete from reports where world = w and target = tgt.user_id;   -- start over after the sanction
    return jsonb_build_object('ok', true, 'muted', true);
  end if;
  return jsonb_build_object('ok', true, 'muted', false);
end $$;

-- ---------- 3. client errors ----------
create table if not exists public.client_errors (
  id      bigint generated always as identity primary key,
  user_id uuid,
  world   text,
  msg     text        not null,
  stack   text,
  src     text,
  ua      text,
  n       integer     not null default 1,
  at      timestamptz not null default now()
);
create index if not exists client_errors_at on public.client_errors (at);
alter table public.client_errors enable row level security; -- no policy: read from the Supabase dashboard

create or replace function public.log_error(w text, msg text, stack text, src text, ua text) returns void
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); m text := left(coalesce(msg, '?'), 500); last_id bigint;
begin
  if me is null then return; end if;
  if not _rate(me, 'error', 0.1, 10) then return; end if;
  -- same error, same player, within the hour: count instead of duplicating
  select id into last_id from client_errors where user_id = me and client_errors.msg = m and at > now() - interval '1 hour' limit 1;
  if last_id is not null then
    update client_errors set n = n + 1, at = now() where id = last_id;
  else
    insert into client_errors (user_id, world, msg, stack, src, ua)
      values (me, left(w, 32), m, left(stack, 2000), left(src, 300), left(ua, 300));
  end if;
  if random() < 0.02 then delete from client_errors where at < now() - interval '14 days'; end if;
end $$;

-- ---------- 4. rights and broadcast ----------
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_'
             or p.proname in ('set_recovery_code', 'claim_recovery', 'log_error')) loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;
do $$ begin
  begin alter publication supabase_realtime add table public.chat; exception when duplicate_object then null; end;
end $$;

-- ════════════════ 004_chests.sql ════════════════
-- 004: chests (placeable storage). Each chest's contents are kept by the server.
--   act_chest reads a chest; act_chest_move deposits (n > 0) or withdraws (n < 0) items from the bag.
--   Opening a chest: must be in reach, and able to build there (inside a claim: owner and guests only;
--   elsewhere: anyone).
--   A broken chest returns its contents to whoever broke it.
-- Requires 002_security.sql. The chest block (98) comes from rules.sql. Replayable without error.

create table if not exists public.chests (
  world text  not null,
  x     int   not null,
  y     int   not null,
  z     int   not null,
  items jsonb not null default '{}'::jsonb,   -- { "item": count }
  primary key (world, x, y, z)
);
alter table public.chests enable row level security; -- no policy: functions only

create or replace function public._chest_ok(me uuid, w text, px int, py int, pz int, ex real, ey real, ez real) returns text
language plpgsql security definer set search_path = public as $$
declare e text;
begin
  if not _rate(me, 'chest', 6, 12) then return 'too many actions'; end if;
  e := _check_pos(me, w, ex, ey, ez, px, py, pz);
  if e is not null then return e; end if;
  if _cell(w, px, py, pz) <> 98 then return 'no chest here'; end if;
  if not _can_build(me, w, px, pz) then return 'protected'; end if;
  return null;
end $$;

create or replace function public.act_chest(w text, px int, py int, pz int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text := _chest_ok(me, w, px, py, pz, ex, ey, ez);
begin
  if e is not null then return _no(e); end if;
  return jsonb_build_object('ok', true, 'items',
    coalesce((select items from chests where world = w and x = px and y = py and z = pz), '{}'::jsonb));
end $$;

create or replace function public.act_chest_move(w text, px int, py int, pz int, item int, n int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text := _chest_ok(me, w, px, py, pz, ex, ey, ez);
        cur jsonb; have int; inv jsonb := '{}'::jsonb;
begin
  if e is not null then return _no(e); end if;
  if n = 0 or abs(n) > 10000 then return _no('invalid quantity'); end if;
  insert into chests (world, x, y, z) values (w, px, py, pz) on conflict do nothing;
  select items into cur from chests where world = w and x = px and y = py and z = pz for update;
  if cur is null or _cell(w, px, py, pz) <> 98 then return _no('no chest here'); end if;
  have := coalesce((cur ->> item::text)::int, 0);
  if n > 0 then
    if _count(me, w, item) < n then return _no('not enough in your bag'); end if;
    if have = 0 and (select count(*) from jsonb_object_keys(cur)) >= 27 then return _no('chest full'); end if;
    inv := _give(me, w, item, -n, inv);
    cur := cur || jsonb_build_object(item::text, have + n);
  else
    n := greatest(n, -have);
    if n = 0 then return _no('none of that item in the chest'); end if;
    inv := _give(me, w, item, -n, inv);
    cur := case when have + n = 0 then cur - item::text else cur || jsonb_build_object(item::text, have + n) end;
  end if;
  update chests set items = cur where world = w and x = px and y = py and z = pz;
  return jsonb_build_object('ok', true, 'items', cur, 'inv', inv);
end $$;

-- Chest broken or replaced: its contents go into the bag of whoever broke it.
-- Deleting locks the row first: a move in progress waits, then finds nothing left (no double payout).
create or replace function public._chest_broken() returns trigger
language plpgsql security definer set search_path = public as $$
declare it jsonb; k text; v text; inv jsonb := '{}'::jsonb;
begin
  if new.id = 98 then return new; end if;
  delete from chests where world = new.world and x = new.x and y = new.y and z = new.z returning items into it;
  if it is null or auth.uid() is null then return new; end if;
  for k, v in select * from jsonb_each_text(it) loop
    inv := _give(auth.uid(), new.world, k::int, v::int, inv);
  end loop;
  return new;
end $$;
drop trigger if exists chest_broken on public.blocks;
create trigger chest_broken after insert or update of id on public.blocks
  for each row execute function public._chest_broken();

-- rights: only act_* callable by players
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 005_usernames.sql ════════════════
-- 005: username hardening.
--   Usernames: 20 characters at most, unique in a world (case-insensitive); valid color.
--   Prevents impersonating another player (chat, claim invites, reports).
--   "New game" goes through act_new_game instead of deleting/moving the player record (which would
--   reset its counters: today's gifts, position, mining pace, mute status...).
-- Requires 001_schema.sql, 002_security.sql. Replayable without error.

-- the player only sees their own record (RLS): the uniqueness check runs with the server's rights.
-- No "_" prefix: the migrations' rights loops don't lock it down (it only reveals whether a username is taken).
create or replace function public.is_username_taken(w text, uname text, uid uuid, previous uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from players p where p.world = w and lower(p.name) = lower(uname)
                 and p.user_id <> uid and p.user_id is distinct from previous)
$$;

create or replace function public._players_guard() returns trigger
language plpgsql set search_path = public as $$
declare n text;
begin
  -- server functions (security definer) run as the owner: only they change these columns
  if current_user in ('authenticated', 'anon') and tg_op = 'UPDATE'
     and (new.user_id <> old.user_id or new.world <> old.world) then
    raise exception 'player record can''t be modified';
  end if;
  -- latin letters (accents included), digits, space, _ . - : no invisible characters or lookalikes (cyrillic...)
  n := nullif(left(btrim(regexp_replace(coalesce(new.name, ''), '[^A-Za-z0-9À-ÖØ-öø-ÿ _.-]', '', 'g')), 20), '');
  new.name := n;
  if new.color is null or new.color !~ '^#[0-9a-fA-F]{6}$' then new.color := '#8a7bef'; end if;
  -- uniqueness checked when the username changes (not when the server moves a record, e.g. recovery code)
  if n is not null and (tg_op = 'INSERT' or lower(n) is distinct from lower(old.name))
     and is_username_taken(new.world, n, new.user_id, case when tg_op = 'UPDATE' then old.user_id end) then
    raise exception 'username already taken';
  end if;
  return new;
end $$;
drop trigger if exists players_guard on public.players;
create trigger players_guard before insert or update on public.players
  for each row execute function public._players_guard();
-- the unique index also settles simultaneous signups under the same username
create unique index if not exists players_username on public.players (world, lower(name)) where name is not null;

-- "New game": clears the saved game state in the player record, without touching server-side counters.
create or replace function public.act_new_game(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'newgame', 0.05, 2) then return _no('too many actions'); end if;
  update players set state = '{}'::jsonb where user_id = me and world = w;
  return jsonb_build_object('ok', true);
end $$;

-- ---------- rights ----------
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;
grant execute on function public._rate(uuid, text, real, real) to service_role;
revoke all on function public.is_username_taken(text, text, uuid, uuid) from public, anon;
grant execute on function public.is_username_taken(text, text, uuid, uuid) to authenticated;

-- ════════════════ 006_public_zones.sql ════════════════
-- 006: protected public zones. No one can mine, place, or claim there:
--   the Atrium (radius 7.9 around the sanctuary validator, at 8, 8);
--   the City (radius 30.5 around 8, -56).
-- Same measurements as the generator (supabase/functions/_shared/world.js: SPAWN, CITY) and the game (06-actions.js).
-- Requires 001_schema.sql, 002_security.sql. Replayable without error.

create or replace function public._public_zone(px int, pz int) returns boolean
language sql immutable as $$
  select sqrt((px - 8) ^ 2 + (pz - 8) ^ 2) <= 7.9 or sqrt((px - 8) ^ 2 + (pz + 56) ^ 2) <= 30.5
$$;

create or replace function public._can_build(me uuid, w text, px int, pz int) returns boolean
language sql stable security definer set search_path = public as $$
  select not _public_zone(px, pz)
     and not exists (select 1 from claims c where c.world = w and c.cx = px >> 4 and c.cz = pz >> 4
                     and c.owner <> me and not (me = any (c.members)))
$$;

-- no claim on a chunk that touches a public zone
create or replace function public.act_claim(w text, qx int, qz int, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text;
begin
  if not _rate(me, 'claim', 0.5, 3) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  if floor(ex)::int >> 4 <> qx or floor(ez)::int >> 4 <> qz then return _no('must be inside the claim'); end if;
  if exists (select 1 from generate_series(0, 15) a, generate_series(0, 15) b where _public_zone(qx * 16 + a, qz * 16 + b)) then
    return _no('this place belongs to everyone');
  end if;
  return _core_claim(w, qx, qz);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;
grant execute on function public._rate(uuid, text, real, real) to service_role;

-- ════════════════ 007_network.sql ════════════════
-- 007: the network, the world's shared goal.
--   act_network counts relit dark validators (block 74) across all players, and names the five players
--   who have relit the most. The game shows it in the quest log and animates the great diamond.
-- Requires 001_schema.sql, 002_security.sql. Replayable without error.

create index if not exists blocks_network on public.blocks (world, placed_by) where id = 74;

create or replace function public.act_network(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); total int; top jsonb;
begin
  if not _rate(me, 'network', 0.2, 5) then return _no('too many actions'); end if;
  select count(*) into total from blocks where world = w and id = 74;
  select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'n', t.c) order by t.c desc, t.name), '[]'::jsonb) into top
    from (select coalesce(max(placed_name), 'anonymous') as name, count(*) as c from blocks
           where world = w and id = 74 group by placed_by order by count(*) desc limit 5) t;
  return jsonb_build_object('ok', true, 'n', total, 'top', top);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;
grant execute on function public._rate(uuid, text, real, real) to service_role;

-- ════════════════ 008_trades.sql ════════════════
-- 008: trading between players. A player proposes an offer to another, by username:
--   "give" and "want" can contain resources, unique items, and claims.
--   give: { "items": { "101": 5 }, "uniques": [serial numbers from the proposer], "parcels": [[cx, cz], ...] }
--   want: { "items": { ... },       "uniques": [item types: 201, 202],            "parcels": [[cx, cz], ...] }
--   Nothing is locked at creation: everything is re-checked on acceptance, and the trade then happens
--   all at once (all or nothing). Validator seals (203) can't be traded: they prove an achievement.
-- Requires 001_schema.sql, 002_security.sql, 005_usernames.sql. Replayable without error.

create table if not exists public.offers (
  id         bigint generated always as identity primary key,
  world      text        not null,
  from_user  uuid        not null references auth.users (id) on delete cascade,
  from_name  text        not null,
  to_user    uuid        not null references auth.users (id) on delete cascade,
  to_name    text        not null,
  give       jsonb       not null,
  want       jsonb       not null,
  status     text        not null default 'open' check (status in ('open', 'accepted', 'declined', 'canceled')),
  created_at timestamptz not null default now(),
  closed_at  timestamptz
);
create index if not exists offers_from on public.offers (world, from_user) where status = 'open';
create index if not exists offers_to on public.offers (world, to_user) where status = 'open';
alter table public.offers enable row level security;
drop policy if exists "read own offers" on public.offers;
create policy "read own offers" on public.offers for select to authenticated using (auth.uid() in (from_user, to_user));
revoke insert, update, delete on public.offers from anon, authenticated;

-- Normalizes one side of an offer (or raises an error if malformed): nothing but the three lists,
-- positive integer quantities, no duplicates, bounded sizes.
create or replace function public._offer_shape(p jsonb) returns jsonb
language plpgsql immutable as $$
declare items jsonb := '{}'; uni jsonb := '[]'; par jsonb := '[]'; k text; v jsonb; e jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'object' then return jsonb_build_object('items', items, 'uniques', uni, 'parcels', par); end if;
  if jsonb_typeof(p -> 'items') = 'object' then
    for k, v in select * from jsonb_each(p -> 'items') loop
      if k !~ '^[0-9]{1,4}$' or jsonb_typeof(v) <> 'number' or (v #>> '{}') !~ '^[0-9]{1,6}$' or (v #>> '{}')::int < 1 then
        raise exception 'invalid offer';
      end if;
      if k::int >= 200 then raise exception 'invalid offer'; end if;  -- unique items go in "uniques"
      items := items || jsonb_build_object(k::int::text, (v #>> '{}')::int);
    end loop;
  end if;
  if jsonb_typeof(p -> 'uniques') = 'array' then
    for e in select * from jsonb_array_elements(p -> 'uniques') loop
      if jsonb_typeof(e) <> 'number' or (e #>> '{}') !~ '^[0-9]{1,9}$' then raise exception 'invalid offer'; end if;
      if not exists (select 1 from jsonb_array_elements(uni) x(v) where x.v = e) then uni := uni || e; end if;
    end loop;
  end if;
  if jsonb_typeof(p -> 'parcels') = 'array' then
    for e in select * from jsonb_array_elements(p -> 'parcels') loop
      if jsonb_typeof(e) <> 'array' or jsonb_array_length(e) <> 2
         or (e ->> 0) !~ '^-?[0-9]{1,6}$' or (e ->> 1) !~ '^-?[0-9]{1,6}$' then raise exception 'invalid offer'; end if;
      e := jsonb_build_array((e ->> 0)::int, (e ->> 1)::int);
      if not exists (select 1 from jsonb_array_elements(par) x(v) where x.v = e) then par := par || jsonb_build_array(e); end if;
    end loop;
  end if;
  if (select count(*) from jsonb_object_keys(items)) > 8 or jsonb_array_length(uni) > 4 or jsonb_array_length(par) > 4 then
    raise exception 'offer too long';
  end if;
  return jsonb_build_object('items', items, 'uniques', uni, 'parcels', par);
end $$;

create or replace function public._offer_empty(p jsonb) returns boolean language sql immutable as $$
  select p -> 'items' = '{}'::jsonb and p -> 'uniques' = '[]'::jsonb and p -> 'parcels' = '[]'::jsonb $$;

-- Does this player have everything on this side of the offer? Returns null, or what's missing.
--   by_type = false: "uniques" lists serial numbers (proposer's side);
--   by_type = true  : "uniques" lists item types (recipient's side), a different item per requested type.
create or replace function public._offer_missing(who uuid, w text, p jsonb, by_type boolean) returns text
language plpgsql stable security definer set search_path = public as $$
declare k text; v text; e jsonb; n int;
begin
  for k, v in select * from jsonb_each_text(p -> 'items') loop
    if _count(who, w, k::int) < v::int then return 'resources'; end if;
  end loop;
  if by_type then
    for k, v in select t.x, count(*)::text from jsonb_array_elements_text(p -> 'uniques') t(x) group by t.x loop
      select count(*) into n from uniques where user_id = who and world = w and item = k::int and item <> 203;
      if n < v::int then return 'unique item'; end if;
    end loop;
  else
    for e in select * from jsonb_array_elements(p -> 'uniques') loop
      if not exists (select 1 from uniques where user_id = who and world = w and serial = (e #>> '{}')::int and item <> 203) then
        return 'unique item';
      end if;
    end loop;
  end if;
  for e in select * from jsonb_array_elements(p -> 'parcels') loop
    if not exists (select 1 from claims where world = w and cx = (e ->> 0)::int and cz = (e ->> 1)::int and owner = who) then
      return 'claim';
    end if;
  end loop;
  return null;
end $$;

-- Moves one side of the offer from a to b (everything already checked beforehand).
create or replace function public._offer_transfer(a uuid, b uuid, bname text, w text, p jsonb, by_type boolean) returns void
language plpgsql security definer set search_path = public as $$
declare k text; v text; e jsonb; u uniques; s int; mem uuid[];
begin
  for k, v in select * from jsonb_each_text(p -> 'items') loop
    perform _give(a, w, k::int, -v::int, '{}'::jsonb);
    perform _give(b, w, k::int, v::int, '{}'::jsonb);
  end loop;
  for e in select * from jsonb_array_elements(p -> 'uniques') loop
    if by_type then
      select * into u from uniques where user_id = a and world = w and item = (e #>> '{}')::int and item <> 203 order by serial limit 1;
    else
      select * into u from uniques where user_id = a and world = w and serial = (e #>> '{}')::int and item <> 203;
    end if;
    if u.user_id is null then raise exception 'unique item not found'; end if;
    delete from uniques where user_id = a and world = w and serial = u.serial;
    -- the item keeps its history (forge place, blocks mined, date); it gets a new number under its new owner
    select coalesce(max(serial), 0) + 1 into s from uniques where user_id = b and world = w;
    insert into uniques (user_id, world, serial, item, place, mined, created_at) values (b, w, s, u.item, u.place, u.mined, u.created_at);
  end loop;
  select members into mem from claims where world = w and owner = b limit 1;
  for e in select * from jsonb_array_elements(p -> 'parcels') loop
    update claims set owner = b, owner_name = bname, members = coalesce(mem, '{}')
     where world = w and cx = (e ->> 0)::int and cz = (e ->> 1)::int and owner = a;
    if not found then raise exception 'claim not found'; end if;
  end loop;
end $$;

-- Propose a trade to a player, by username.
create or replace function public.act_offer(w text, username text, give jsonb, want jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); mine players; them players; g jsonb; q jsonb; m text; oid bigint;
begin
  if not _rate(me, 'offer', 0.1, 4) then return _no('too many actions'); end if;
  select * into mine from players where user_id = me and world = w;
  if coalesce(btrim(mine.name), '') = '' then return _no('you need a username'); end if;
  select * into them from players where world = w and lower(name) = lower(btrim(username)) and user_id <> me limit 1;
  if them.user_id is null then return _no('unknown player in this world'); end if;
  begin
    g := _offer_shape(give);
    q := _offer_shape(want);
  exception when others then return _no('invalid offer'); end;
  if _offer_empty(g) then return _no('you must give something'); end if;
  m := _offer_missing(me, w, g, false);
  if m is not null then return _no('you don''t have everything you''re offering', jsonb_build_object('missing', m)); end if;
  m := _offer_missing(them.user_id, w, q, true);
  if m is not null then return _no('that player doesn''t have what you''re asking for', jsonb_build_object('missing', m)); end if;
  update offers set status = 'canceled', closed_at = now() where status = 'open' and created_at < now() - interval '3 days';
  if (select count(*) from offers where world = w and from_user = me and status = 'open') >= 5 then
    return _no('5 pending offers at most');
  end if;
  insert into offers (world, from_user, from_name, to_user, to_name, give, want)
    values (w, me, mine.name, them.user_id, them.name, g, q) returning id into oid;
  if random() < 0.05 then delete from offers where status <> 'open' and closed_at < now() - interval '14 days'; end if;
  return jsonb_build_object('ok', true, 'id', oid, 'name', them.name);
end $$;

-- Accept a received offer: both sides are re-checked, then everything changes hands at once.
create or replace function public.act_offer_accept(w text, oid bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); o offers; m text; na int; nb int; mine players;
begin
  if not _rate(me, 'offer_accept', 0.5, 4) then return _no('too many actions'); end if;
  select * into o from offers where id = oid and world = w for update;
  if o.id is null or o.to_user <> me then return _no('offer not found'); end if;
  if o.status <> 'open' or o.created_at < now() - interval '3 days' then return _no('this offer is no longer open'); end if;
  -- both records are locked, always in the same order
  perform 1 from players where world = w and user_id in (o.from_user, o.to_user) order by user_id for update;
  perform 1 from claims where world = w and owner in (o.from_user, o.to_user) order by cx, cz for update;
  m := _offer_missing(o.from_user, w, o.give, false);
  if m is not null then return _no('the other player no longer has what they offered', jsonb_build_object('missing', m)); end if;
  m := _offer_missing(me, w, o.want, true);
  if m is not null then return _no('you don''t have what''s requested', jsonb_build_object('missing', m)); end if;
  -- 16 claims at most, after the trade, for each side
  select count(*) into na from claims where world = w and owner = o.from_user;
  select count(*) into nb from claims where world = w and owner = me;
  if na - jsonb_array_length(o.give -> 'parcels') + jsonb_array_length(o.want -> 'parcels') > 16
     or nb - jsonb_array_length(o.want -> 'parcels') + jsonb_array_length(o.give -> 'parcels') > 16 then
    return _no('16 claims at most');
  end if;
  select * into mine from players where user_id = me and world = w;
  perform _offer_transfer(o.from_user, me, coalesce(mine.name, o.to_name), w, o.give, false);
  perform _offer_transfer(me, o.from_user, o.from_name, w, o.want, true);
  update offers set status = 'accepted', closed_at = now() where id = oid;
  return jsonb_build_object('ok', true, 'name', o.from_name);
end $$;

-- Decline a received offer, or cancel a sent one.
create or replace function public.act_offer_close(w text, oid bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); o offers;
begin
  select * into o from offers where id = oid and world = w for update;
  if o.id is null or me not in (o.from_user, o.to_user) then return _no('offer not found'); end if;
  if o.status <> 'open' then return _no('this offer is no longer open'); end if;
  update offers set status = case when me = o.from_user then 'canceled' else 'declined' end, closed_at = now() where id = oid;
  return jsonb_build_object('ok', true);
end $$;

-- This player's pending offers, received and sent.
create or replace function public.act_offers(w text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w);
begin
  if not _rate(me, 'offers', 0.5, 8) then return _no('too many actions'); end if;
  return jsonb_build_object('ok', true, 'offers', coalesce((
    select jsonb_agg(jsonb_build_object('id', id, 'from', from_name, 'to', to_name, 'mine', from_user = me,
                                        'give', give, 'want', want, 'at', created_at,
                                        -- the unique items offered, described (the recipient can't see the other's inventory)
                                        'uniqueDetails', coalesce((select jsonb_agg(jsonb_build_object('serial', u.serial, 'item', u.item, 'mined', u.mined) order by u.serial)
                                                              from uniques u where u.user_id = o.from_user and u.world = w
                                                               and u.serial in (select (x.v #>> '{}')::int from jsonb_array_elements(o.give -> 'uniques') x(v))), '[]'::jsonb))
                             order by created_at desc)
      from offers o where world = w and status = 'open' and me in (from_user, to_user)
       and created_at > now() - interval '3 days'), '[]'::jsonb));
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;
grant execute on function public._rate(uuid, text, real, real) to service_role;
do $$ begin
  begin alter publication supabase_realtime add table public.offers; exception when duplicate_object then null; when undefined_object then null; end;
end $$;

-- ════════════════ 009_onchain_wallet.sql ════════════════
-- 009: onchain wallet linking.
--   A wallet can be linked to an account (one per account, independent of world) via a signed message,
--   verified by the Edge Function; no key or secret here. Nothing else is tokenized.
--   The validator seal (203)'s onchain fields (vx, vy, vz, chain_tx, token_id) live directly on the
--   base "uniques" table (see 001_schema.sql) since there's no legacy data to migrate separately.
-- Requires 001_schema.sql (uniques), 002_security.sql (_rate). Replayable without error.

create table if not exists public.wallets (
  user_id    uuid        primary key references auth.users (id) on delete cascade,
  address    text        not null unique,
  linked_at  timestamptz not null default now()
);
alter table public.wallets enable row level security;
drop policy if exists "read own wallet" on public.wallets;
create policy "read own wallet" on public.wallets for select to authenticated using (auth.uid() = user_id);

-- One-time challenge to prove ownership of an address (the player signs it, the Edge Function verifies
-- the signature then writes to wallets). Never read by the player: no select policy.
create table if not exists public.wallet_nonces (
  user_id    uuid        primary key references auth.users (id) on delete cascade,
  nonce      text        not null,
  created_at timestamptz not null default now()
);
alter table public.wallet_nonces enable row level security; -- no policy: functions and the Edge Function only

create or replace function public.act_wallet_nonce() returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare me uuid := auth.uid(); n text;
begin
  if me is null then raise exception 'not signed in'; end if;
  if not _rate(me, 'wallet_nonce', 0.1, 4) then return _no('too many actions'); end if;
  n := encode(extensions.gen_random_bytes(16), 'hex');
  insert into wallet_nonces (user_id, nonce) values (me, n)
    on conflict (user_id) do update set nonce = excluded.nonce, created_at = now();
  return jsonb_build_object('ok', true, 'nonce', n);
end $$;

do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig, p.proname as name from pg_proc p join pg_namespace s on s.oid = p.pronamespace
           where s.nspname = 'public' and (left(p.proname, 1) = '_' or left(p.proname, 4) = 'act_') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if left(f.name, 1) <> '_' then execute format('grant execute on function %s to authenticated', f.sig); end if;
  end loop;
end $$;

-- ════════════════ 010_bed.sql ════════════════
-- Migration 010: a proper 2-block bed (foot + head), same multi-block pattern as Door.
-- rule_blocks has no facing column, so the facing is encoded directly in kind ('bed0f'..'bed3h');
-- the (dx,dz) offset to the other half is computed with an explicit CASE on kind (never string parsing,
-- since this runs in a security definer function).

create or replace function public._core_mine(w text, px int, py int, pz int, held text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; id0 int; rb rule_blocks; t_tier int := 0; t_mult real := 1; useri int;
  need real; ch jsonb := '[]'; inv jsonb := '{}'; oy int; other int; above int; ab rule_blocks; n int; odx int; odz int;
begin
  pl := _player(me, w);
  id0 := _cell(w, px, py, pz);
  select * into rb from rule_blocks where id = id0;
  if id0 = 0 or rb.id is null or rb.hard is null then return _no('nothing to mine', jsonb_build_object('cell', id0)); end if;
  if not _can_build(me, w, px, pz) then return _no('protected', jsonb_build_object('cell', id0)); end if;
  if held = '102' and _count(me, w, 102) > 0 then
    select tier, rule_items.tool into t_tier, t_mult from rule_items where id = 102;
  elsif held like 'nft%' then
    select u.serial, i.tier, i.tool into useri, t_tier, t_mult from uniques u join rule_items i on i.id = u.item
      where u.user_id = me and u.world = w and u.serial = nullif(substr(held, 4), '')::int;
    t_tier := coalesce(t_tier, 0); t_mult := coalesce(t_mult, 1);
  end if;
  if t_tier < rb.tier then return _no('tool too weak', jsonb_build_object('cell', id0)); end if;
  need := rb.hard / t_mult;
  if pl.mine_at is not null and extract(epoch from clock_timestamp() - pl.mine_at) < need * 0.5 - 0.1 then
    return _no('too fast', jsonb_build_object('cell', id0));
  end if;
  update players set mine_at = clock_timestamp() where user_id = me and world = w;
  ch := ch || _set(w, px, py, pz, 0, null, null, null);
  if rb.kind = 'door' then
    oy := case when rb.top then py - 1 else py + 1 end; other := _cell(w, px, oy, pz);
    if (select kind from rule_blocks where id = other) = 'door' then ch := ch || _set(w, px, oy, pz, 0, null, null, null); end if;
  elsif rb.kind like 'bed%' then
    odx := case rb.kind
      when 'bed0f' then 0 when 'bed1f' then -1 when 'bed2f' then 0 when 'bed3f' then 1
      when 'bed0h' then 0 when 'bed1h' then 1 when 'bed2h' then 0 when 'bed3h' then -1 end;
    odz := case rb.kind
      when 'bed0f' then -1 when 'bed1f' then 0 when 'bed2f' then 1 when 'bed3f' then 0
      when 'bed0h' then 1 when 'bed1h' then 0 when 'bed2h' then -1 when 'bed3h' then 0 end;
    other := _cell(w, px + odx, py, pz + odz);
    if (select kind from rule_blocks where id = other) like 'bed%' then
      ch := ch || _set(w, px + odx, py, pz + odz, 0, null, null, null);
    end if;
  end if;
  above := _cell(w, px, py + 1, pz); select * into ab from rule_blocks where id = above;
  if ab.kind = 'cross' then ch := ch || _set(w, px, py + 1, pz, 0, null, null, null);
  elsif ab.kind in ('plate', 'cable', 'lever') then
    ch := ch || _set(w, px, py + 1, pz, 0, null, null, null);
    if ab.drop_item is not null then inv := _give(me, w, ab.drop_item, 1, inv); end if;
  end if;
  n := case rb.drop_item when 101 then 1 + (random() < 0.4)::int when 104 then (random() < 0.4)::int else 1 end;
  if rb.drop_item is not null and n > 0 then inv := _give(me, w, rb.drop_item, n, inv); end if;
  if useri is not null then update uniques set mined = mined + 1 where user_id = me and world = w and serial = useri; end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'got', jsonb_build_object('item', rb.drop_item, 'n', n));
end $$;

-- Place: the item is in the inventory, the cell is free, the support is right.
create or replace function public._core_place(w text, px int, py int, pz int, it int, bid int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; cur int; cr rule_blocks; rb rule_blocks; below int; up int; ch jsonb := '[]'; inv jsonb := '{}'; s int;
  odx int; odz int; ocur int; ocr rule_blocks;
begin
  pl := _player(me, w);
  if py < 1 or py >= 64 or abs(px) >= 100000 or abs(pz) >= 100000 then return _no('out of the world'); end if;
  if not exists (select 1 from rule_place where item = it and block = bid) then return _no('item not placeable'); end if;
  if _count(me, w, it) < 1 then return _no('empty inventory', jsonb_build_object('inv', jsonb_build_object(it::text, 0))); end if;
  if not _can_build(me, w, px, pz) then return _no('protected'); end if;
  cur := _cell(w, px, py, pz); select * into cr from rule_blocks where id = cur;
  if cur <> 0 and cr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', cur)); end if;
  select * into rb from rule_blocks where id = bid;
  below := _cell(w, px, py - 1, pz);
  if rb.kind = 'cross' and below not in (1, 2) then return _no('needs support'); end if;
  if rb.kind in ('plate', 'cable', 'lever') and not coalesce((select solid from rule_blocks where id = below), false) then return _no('needs support'); end if;
  if rb.kind = 'door' then
    if py + 1 >= 64 then return _no('out of the world'); end if;
    up := _cell(w, px, py + 1, pz);
    if up <> 0 and (select kind from rule_blocks where id = up) not in ('water', 'cross') then return _no('space occupied'); end if;
  elsif rb.kind like 'bed%f' then
    odx := case rb.kind when 'bed0f' then 0 when 'bed1f' then -1 when 'bed2f' then 0 when 'bed3f' then 1 end;
    odz := case rb.kind when 'bed0f' then -1 when 'bed1f' then 0 when 'bed2f' then 1 when 'bed3f' then 0 end;
    ocur := _cell(w, px + odx, py, pz + odz); select * into ocr from rule_blocks where id = ocur;
    if ocur <> 0 and ocr.kind not in ('water', 'cross') then return _no('space occupied', jsonb_build_object('cell', ocur)); end if;
  end if;
  inv := _give(me, w, it, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, bid, me, pl.name, s);
  if rb.kind = 'door' then ch := ch || _set(w, px, py + 1, pz, bid + 1, me, pl.name, s);
  elsif rb.kind like 'bed%f' then ch := ch || _set(w, px + odx, py, pz + odz, bid + 4, me, pl.name, s);
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'serial', s);
end $$;

-- ════════════════ 011_toggle_public.sql ════════════════
-- 011: opening/closing a door or lever is reversible (not mining, placing, or claiming), so it stays allowed
-- in public zones (the Atrium, the City) — otherwise a door placed there by the generator can never be opened.
-- Still respects other players' claims. Requires 001_schema.sql, 006_public_zones.sql. Replayable without error.

create or replace function public._can_toggle(me uuid, w text, px int, pz int) returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (select 1 from claims c where c.world = w and c.cx = px >> 4 and c.cz = pz >> 4
                      and c.owner <> me and not (me = any (c.members)))
$$;

create or replace function public._core_toggle(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); cur int; rb rule_blocks; ch jsonb := '[]'; oy int; other int;
begin
  perform _player(me, w);
  cur := _cell(w, px, py, pz); select * into rb from rule_blocks where id = cur;
  if rb.kind not in ('door', 'lever') then return _no('nothing to toggle', jsonb_build_object('cell', cur)); end if;
  if not _can_toggle(me, w, px, pz) then return _no('protected'); end if;
  if rb.kind = 'lever' then return jsonb_build_object('ok', true, 'changes', ch || _flip(w, px, py, pz, case cur when 64 then 65 else 64 end)); end if;
  ch := ch || _flip(w, px, py, pz, cur # 2);
  oy := case when rb.top then py - 1 else py + 1 end; other := _cell(w, px, oy, pz);
  if (select kind from rule_blocks where id = other) = 'door' then ch := ch || _flip(w, px, oy, pz, other # 2); end if;
  return jsonb_build_object('ok', true, 'changes', ch);
end $$;

revoke all on function public._can_toggle(uuid, text, int, int) from public, anon, authenticated;

-- ════════════════ 012_relight_column.sql ════════════════
-- 012: a dark validator can't be relit until the ruin's fourth broken column (its +x, +z corner,
-- supabase/functions/_shared/world.js: the 4th entry of the [dx,dz] column list) is rebuilt back
-- to its full height — any solid blocks will do, not necessarily the original marble/mossy-stone.
-- Requires 001_schema.sql, 002_security.sql (_cell_soft). Replayable without error.

create or replace function public._core_relight(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}'; s int; ch jsonb := '[]'; u jsonb; solid boolean;
begin
  pl := _player(me, w);
  if _cell(w, px, py, pz) <> 73 then return _no('not a dark validator', jsonb_build_object('cell', _cell(w, px, py, pz))); end if;
  for i in 0..2 loop
    -- the column's chunk may not be frozen yet even though the validator's is: _cell_soft, not _cell, so an
    -- un-frozen neighbor reads as "not solid" (a clean refusal) instead of raising
    solid := coalesce((select rb.solid from rule_blocks rb where rb.id = _cell_soft(w, px + 2, py + i, pz + 2)), false);
    if not solid then return _no('rebuild the fourth column first'); end if;
  end loop;
  if _count(me, w, 105) < 1 then return _no('needs a validator heart'); end if;
  inv := _give(me, w, 105, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, 74, me, pl.name, s);
  u := _mint(me, w, 203, px || ', ' || py || ', ' || pz);
  update uniques set vx = px, vy = py, vz = pz where user_id = me and world = w and serial = (u ->> 'serial')::int;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'unique', u, 'serial', s);
end $$;

-- ════════════════ 013_mob_loot.sql ════════════════
-- 013: hostile mobs drop a thematic resource on death — a modest, chance-based bonus layered on top of
-- mining, not a replacement for it. Mobs have no server-side presence (deterministic from the seed, like
-- animals), so this trusts the client-reported mob type the same way _core_mine already trusts "held" for
-- tool tier: bounded by position plausibility and a conservative rate limit, not independently re-derived.
-- Requires 001_schema.sql, 002_security.sql (_me_or_fail, _rate, _check_pos, _give). Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real;
begin
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;
revoke all on function public.act_loot_mob(text, text, real, real, real) from public, anon, authenticated;
grant execute on function public.act_loot_mob(text, text, real, real, real) to authenticated;

-- ════════════════ 014_relight_capstone.sql ════════════════
-- 014: a real payoff for the network's shared milestones (supabase/migrations/007_network.sql's TIERS
-- [3, 10, 25, 50, 100]), which until now were pure flavor text and an orbiting star mesh. Whoever's relight
-- crosses a tier mints a one-of-a-kind Validator Star (#204) commemorating it — same mechanism as the
-- existing Validator Seal (#203). And once the network is fully awake (tier 100 crossed), every relight
-- from then on has a chance of also returning a Diamond Shard (#110), the ingredient for the new Radiant
-- Diamond block (#145) — so the reward keeps flowing to everyone who keeps relighting, not just whoever
-- happened to cross the 100th threshold. Requires 001_schema.sql, 002_security.sql (_cell_soft). Replayable
-- without error.

create or replace function public._core_relight(w text, px int, py int, pz int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); pl players; inv jsonb := '{}'; s int; ch jsonb := '[]'; u jsonb; star jsonb; solid boolean; relit_n int; shard boolean := false;
begin
  pl := _player(me, w);
  if _cell(w, px, py, pz) <> 73 then return _no('not a dark validator', jsonb_build_object('cell', _cell(w, px, py, pz))); end if;
  for i in 0..2 loop
    -- the column's chunk may not be frozen yet even though the validator's is: _cell_soft, not _cell, so an
    -- un-frozen neighbor reads as "not solid" (a clean refusal) instead of raising
    solid := coalesce((select rb.solid from rule_blocks rb where rb.id = _cell_soft(w, px + 2, py + i, pz + 2)), false);
    if not solid then return _no('rebuild the fourth column first'); end if;
  end loop;
  if _count(me, w, 105) < 1 then return _no('needs a validator heart'); end if;
  inv := _give(me, w, 105, -1, inv);
  update players set serial = serial + 1 where user_id = me and world = w returning serial into s;
  ch := ch || _set(w, px, py, pz, 74, me, pl.name, s);
  u := _mint(me, w, 203, px || ', ' || py || ', ' || pz);
  update uniques set vx = px, vy = py, vz = pz where user_id = me and world = w and serial = (u ->> 'serial')::int;
  select count(*) into relit_n from blocks where world = w and id = 74;
  if relit_n = any (array[3, 10, 25, 50, 100]) then
    star := _mint(me, w, 204, 'crossed the ' || relit_n || '-relit threshold');
  end if;
  if relit_n >= 100 and random() < 0.15 then
    inv := _give(me, w, 110, 1, inv);
    shard := true;
  end if;
  return jsonb_build_object('ok', true, 'changes', ch, 'inv', inv, 'unique', u, 'star', star, 'shard', shard, 'serial', s);
end $$;

-- ════════════════ 015_boss_loot.sql ════════════════
-- 015: the Genesis Titan (a single, fixed-location boss, src/game/16-mobs.js) always drops its trophy on
-- death — unlike regular mob loot, which is chance-based. Its own rate-limit kind ('loot_boss', burst 1,
-- one claim per ~20s) keeps it independent of the regular 'loot_mob' budget, so grinding ordinary mobs
-- can't be used to bypass it and vice versa. Requires 001_schema.sql, 002_security.sql, 013_mob_loot.sql.
-- Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb;
begin
  if mob_type = 'titan' then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, 205, null);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

-- ════════════════ 016_tower_boss_loot.sql ════════════════
-- 016: towers (src/game/16-mobs.js spawnMobChunk, supabase/functions/_shared/world.js towerAt()) add a
-- repeatable mid-tier boss, the Plasma Core, guaranteed to drop a Plasma Pistol on death — same shape
-- as the Genesis Titan's drop (015_boss_loot.sql), sharing its 'loot_boss' rate-limit bucket so
-- grinding one boss type can't be used to out-pace the other. Tower Wardens get a line in the regular
-- chance-based table alongside the other mobs. Requires 001_schema.sql, 002_security.sql,
-- 013_mob_loot.sql, 015_boss_loot.sql. Replayable without error.

create or replace function public.act_loot_mob(w text, mob_type text, ex real, ey real, ez real) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := _me_or_fail(w); e text; it int; inv jsonb := '{}'; r real; u jsonb;
begin
  if mob_type in ('titan', 'plasma_core') then
    if not _rate(me, 'loot_boss', 0.05, 1) then return _no('too many actions'); end if;
    e := _check_pos(me, w, ex, ey, ez);
    if e is not null then return _no(e); end if;
    u := _mint(me, w, case when mob_type = 'titan' then 205 else 206 end, null);
    return jsonb_build_object('ok', true, 'inv', inv, 'unique', u);
  end if;
  if not _rate(me, 'loot_mob', 0.2, 5) then return _no('too many actions'); end if;
  e := _check_pos(me, w, ex, ey, ez);
  if e is not null then return _no(e); end if;
  r := random();
  it := case mob_type
    when 'shadow' then case when r < 0.5 then 101 end
    when 'guardian' then case when r < 0.35 then 101 when r < 0.5 then 103 end
    when 'sentinel' then case when r < 0.4 then 103 end
    when 'wraith' then case when r < 0.25 then 104 when r < 0.65 then 103 end
    when 'warden' then case when r < 0.3 then 101 when r < 0.45 then 103 end
    else null
  end;
  if it is null then return jsonb_build_object('ok', true, 'inv', inv); end if;
  inv := _give(me, w, it, 1, inv);
  return jsonb_build_object('ok', true, 'inv', inv, 'item', it);
end $$;

